    r += 10; /* shift reg wnd */
    rreserve(MAX_HOSTREGS);
    rc = 4;
    goto jump;

case 1603: /* clo ek r */
    assert(rc == 3);
    { obj* p = objptr_from_obj(r[0]);
    r[1+2] = p[1];
    r[1+3] = p[2];
    r[1+4] = p[3];
    r[1+5] = p[4];
    r[1+6] = p[5]; }
    r += 1; /* shift reg. wnd */
    /* ek r floop objs f fs k */
    { /* cons */ 
    hreserve(hbsz(3), 7); /* 7 live regs */
    *--hp = r[3];  
    *--hp = r[4];  
    *--hp = obj_from_size(PAIR_BTAG); 
    r[7] = (hendblk(3)); }
    r[8+0] = r[2];  
    pc = objptr_from_obj(r[8+0])[0];
    r[8+1] = r[6];  
    r[8+2] = (cdr((r[5])));
    r[8+3] = r[7];  
    r[8+4] = r[1];  
    r += 8; /* shift reg wnd */
    rreserve(MAX_HOSTREGS);
    rc = 5;
    goto jump;

case 1604: /* clo ek . */
    assert(rc >= 2);
    r[2] = obj_from_void(0); /* ignored */
    { obj* p = objptr_from_obj(r[0]);
    r[1+2] = p[1]; }
    r += 1; /* shift reg. wnd */
    /* ek . k */
    r[0] = (cx_exit);
    pc = objptr_from_obj(r[0])[0];
    r[1] = r[2];  
    r[2] = obj_from_fixnum(+1);
    rreserve(MAX_HOSTREGS);
    rc = 3;
    goto jump;

case 1605: /* clo ek . */
    assert(rc >= 2);
    r[2] = obj_from_void(0); /* ignored */
    { obj* p = objptr_from_obj(r[0]);
    r[1+2] = p[1]; }
    r += 1; /* shift reg. wnd */
    /* ek . k */
    hreserve(hbsz(1+1), 3); /* 3 live regs */
    *--hp = r[2];  
    *--hp = obj_from_case(1606);
    r[3] = (hendblk(1+1));
    r[0] = r[3];  
    r[1] = (cx__2Acurrent_2Derror_2Dport_2A);
    goto gs_marv_2Dusage;

case 1606: /* clo ek . */
