case 1609: /* main k argv */
    assert(rc == 3);
    r += 1; /* shift reg. wnd */
    /* k argv */
    hreserve(hbsz(1+1), 2); /* 2 live regs */
    *--hp = r[0];  
    *--hp = obj_from_case(1610);
    r[2] = (hendblk(1+1));
    r[3+0] = (cx_command_2Dline);
    pc = objptr_from_obj(r[3+0])[0];
    r[3+1] = r[2];  
    r += 3; /* shift reg wnd */
    rreserve(MAX_HOSTREGS);
