case 1610: /* clo ek r */
    assert(rc == 3);
    { obj* p = objptr_from_obj(r[0]);
    r[1+2] = p[1]; }
    r += 1; /* shift reg. wnd */
    /* ek r k */
    hreserve(hbsz(1+1), 3); /* 3 live regs */
    *--hp = r[2];  
    *--hp = obj_from_case(1611);
    r[3] = (hendblk(1+1));
    r[0] = r[3];  
    r[1] = ((ispair((r[1]))) ? (cdr((r[1]))) : (mknull()));
    goto gs_marv_2Dmain;

case 1611: /* clo ek . */
    assert(rc >= 2);
    r[2] = obj_from_void(0); /* ignored */
    { obj* p = objptr_from_obj(r[0]);
    r[1+2] = p[1]; }
